param(
  [switch]$Build
)

# aplicar-v100c-corrigir-sobra-topbar-operador.ps1
# Corrige erro:
# Expression expected em OperatorPanel.tsx perto de:
# }: { user: StoredUser | null }) {
#
# Causa:
# A v100b substituiu o inicio do Topbar, mas sobrou um pedaco da funcao antiga.
# Esta versao troca TUDO entre function Topbar e function HeroMetric.

$ErrorActionPreference = "Stop"

$Root = Get-Location
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"

$PanelPath = Join-Path $Root "apps\web\src\app\operator\_components\OperatorPanel.tsx"
$WebDir = Join-Path $Root "apps\web"

function Write-Utf8($Path, $Content) {
  $Dir = Split-Path $Path -Parent
  if (-not (Test-Path $Dir)) {
    New-Item -ItemType Directory -Path $Dir -Force | Out-Null
  }

  $Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Content, $Utf8NoBom)
}

Write-Host "Aplicando v100c - corrigir sobra do Topbar operador..." -ForegroundColor Cyan

if (-not (Test-Path $PanelPath)) {
  throw "Nao encontrei apps\web\src\app\operator\_components\OperatorPanel.tsx"
}

$Backup = "$PanelPath.bak-v100c-$Stamp"
Copy-Item $PanelPath $Backup -Force
Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray

$PatchPath = Join-Path $env:TEMP "v100c-corrigir-sobra-topbar.js"
$Patch = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(""))
Write-Utf8 $PatchPath $Patch

& node $PatchPath $PanelPath

if ($LASTEXITCODE -ne 0) {
  throw "Falha ao aplicar v100c. Envie o erro acima."
}

Write-Host "OperatorPanel corrigido." -ForegroundColor Green

if ($Build) {
  Write-Host ""
  Write-Host "Rodando build do WEB para validar..." -ForegroundColor Cyan
  Push-Location $WebDir
  & cmd.exe /d /s /c "npm run build"
  $BuildExit = $LASTEXITCODE
  Pop-Location

  if ($BuildExit -ne 0) {
    Write-Host ""
    Write-Host "A v100c foi aplicada, mas o build encontrou erro." -ForegroundColor Yellow
    Write-Host "Envie o erro completo. Nao rode scripts antigos por cima." -ForegroundColor Yellow
    exit $BuildExit
  }

  Write-Host "Build do WEB passou." -ForegroundColor Green
} else {
  Write-Host ""
  Write-Host "Build nao executado para nao bloquear por erros antigos de outras telas." -ForegroundColor Yellow
  Write-Host "Para validar depois, rode este script com -Build." -ForegroundColor Yellow
}

Write-Host ""
Write-Host "OK FINAL v100c:" -ForegroundColor Green
Write-Host "- Sobra quebrada do Topbar removida." -ForegroundColor Green
Write-Host "- Header do operador mantido com logo/menu." -ForegroundColor Green
Write-Host ""
Write-Host "Reinicie o WEB:" -ForegroundColor Cyan
Write-Host 'cd "C:\Users\march\OneDrive\Área de Trabalho\plataforma-ingressos\apps\web"' -ForegroundColor Cyan
Write-Host "npm run dev" -ForegroundColor Cyan
